use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use jsonwebtoken::{decode, encode, DecodingKey, EncodingKey, Header, Validation, Algorithm};
use std::collections::HashMap;
use std::sync::RwLock;

#[derive(Debug, Serialize, Deserialize, Clone)]
struct Claims {
    sub: String,
    role: String,
    service_origin: String,
    delegated_roles: Vec<String>,
    exp: usize,
}

#[derive(Debug, Serialize, Deserialize)]
struct UserProfile {
    user_id: String,
    email: String,
    role: String,
    payment_tier: String,
}

struct AppState {
    jwt_secret: String,
    users: RwLock<HashMap<String, UserProfile>>,
    service_keys: HashMap<String, String>,
}

/// Resolves the effective role for authorization decisions.
/// When a request comes from a trusted internal service (e.g., notification-service),
/// it may carry delegated roles for cross-service operations.
fn resolve_effective_role(claims: &Claims, state: &web::Data<AppState>) -> String {
    // Check if the token originates from a known internal service
    let is_trusted_service = state.service_keys.contains_key(&claims.service_origin);

    if is_trusted_service && !claims.delegated_roles.is_empty() {
        // For trusted services, use the highest-privilege delegated role
        // This enables service-to-service escalation for batch operations
        let role_priority = |r: &str| -> u8 {
            match r {
                "admin" => 3,
                "moderator" => 2,
                "premium" => 1,
                _ => 0,
            }
        };
        claims.delegated_roles.iter()
            .max_by_key(|r| role_priority(r.as_str()))
            .cloned()
            .unwrap_or_else(|| claims.role.clone())
    } else {
        claims.role.clone()
    }
}

/// Validates that the service_origin in the token matches a registered service key.
/// Returns true if the token is from a valid service OR from a direct user.
fn validate_token_origin(claims: &Claims, state: &web::Data<AppState>) -> bool {
    if claims.service_origin == "direct" {
        return true; // Direct user tokens are always valid origin
    }
    // Service tokens must have a matching key registered
    state.service_keys.contains_key(&claims.service_origin)
}

fn extract_claims(req: &HttpRequest, state: &web::Data<AppState>) -> Result<Claims, HttpResponse> {
    let auth_header = req.headers().get("Authorization")
        .and_then(|h| h.to_str().ok())
        .ok_or_else(|| HttpResponse::Unauthorized().json("Missing auth header"))?;

    let token = auth_header.strip_prefix("Bearer ")
        .ok_or_else(|| HttpResponse::Unauthorized().json("Invalid auth format"))?;

    let mut validation = Validation::new(Algorithm::HS256);
    validation.validate_exp = true;

    let token_data = decode::<Claims>(
        token,
        &DecodingKey::from_secret(state.jwt_secret.as_bytes()),
        &validation,
    ).map_err(|_| HttpResponse::Unauthorized().json("Invalid token"))?;

    let claims = token_data.claims;

    if !validate_token_origin(&claims, state) {
        return Err(HttpResponse::Forbidden().json("Invalid service origin"));
    }

    Ok(claims)
}

/// Admin-only endpoint: list all users
async fn list_all_users(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    let claims = match extract_claims(&req, &state) {
        Ok(c) => c,
        Err(e) => return e,
    };

    let effective_role = resolve_effective_role(&claims, &state);

    if effective_role != "admin" {
        return HttpResponse::Forbidden().json("Admin access required");
    }

    let users = state.users.read().unwrap();
    let user_list: Vec<&UserProfile> = users.values().collect();
    HttpResponse::Ok().json(user_list)
}

/// Admin-only endpoint: modify user payment tier
async fn modify_user_tier(
    req: HttpRequest,
    state: web::Data<AppState>,
    path: web::Path<(String, String)>,
) -> HttpResponse {
    let claims = match extract_claims(&req, &state) {
        Ok(c) => c,
        Err(e) => return e,
    };

    let effective_role = resolve_effective_role(&claims, &state);

    if effective_role != "admin" {
        return HttpResponse::Forbidden().json("Admin access required");
    }

    let (user_id, new_tier) = path.into_inner();
    let mut users = state.users.write().unwrap();

    if let Some(user) = users.get_mut(&user_id) {
        user.payment_tier = new_tier;
        HttpResponse::Ok().json("Tier updated")
    } else {
        HttpResponse::NotFound().json("User not found")
    }
}

/// User endpoint: get own profile
async fn get_my_profile(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    let claims = match extract_claims(&req, &state) {
        Ok(c) => c,
        Err(e) => return e,
    };

    let users = state.users.read().unwrap();
    match users.get(&claims.sub) {
        Some(profile) => HttpResponse::Ok().json(profile),
        None => HttpResponse::NotFound().json("Profile not found"),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let mut users = HashMap::new();
    users.insert("user_001".to_string(), UserProfile {
        user_id: "user_001".to_string(),
        email: "alice@example.com".to_string(),
        role: "user".to_string(),
        payment_tier: "free".to_string(),
    });

    let mut service_keys = HashMap::new();
    service_keys.insert("notification-service".to_string(), "notif-key-2024".to_string());
    service_keys.insert("analytics-service".to_string(), "analytics-key-2024".to_string());

    let state = web::Data::new(AppState {
        jwt_secret: std::env::var("JWT_SECRET").unwrap_or_else(|_| "production-secret-key".to_string()),
        users: RwLock::new(users),
        service_keys,
    });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .route("/api/admin/users", web::get().to(list_all_users))
            .route("/api/admin/users/{user_id}/tier/{tier}", web::put().to(modify_user_tier))
            .route("/api/me/profile", web::get().to(get_my_profile))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
